package net.officefloor.hq.app.statement;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * A steward cancels the person's last statement: the claims it bound are live again (none goes back to a figure an
 * earlier statement bound) and the statement before it, if any, is the last one shown. Refuses anyone else, or a
 * person with no statement.
 */
public class CancelStatement {
    public void cancel(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Person person,
            Claims claims, Statements statements, Roles roles, Audit audit, Rollup rollup) throws InvalidPersonException {
        if (!Role.STEWARD.equals(roles.of(sheet, user))) {
            throw new InvalidPersonException("Only a steward cancels a statement");
        }
        Statements.Taken last = statements.last(sheet, person.id())
                .orElseThrow(() -> new InvalidPersonException(person.name() + " has no statement to cancel"));
        Rollup.Snapshot before = rollup.take(sheet);
        claims.unbindPerson(sheet, person.id());
        statements.delete(sheet, last.id());
        audit.record("STATEMENT_CANCELLED sheet=" + sheet + " by=" + user + " name=" + person.name() + " due-total="
                + (last.dueTotal() == null ? "n/a" : last.dueTotal().toPlainString()));
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.statement;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** Responds with the statements taken on the sheet, per person. */
public class RespondWithStatements {
    public void respond(@PathVariable("sheet") String sheet, Statements statements,
            ObjectResponse<List<StatementSummary>> response) {
        response.send(statements.list(sheet));
    }
}
package net.officefloor.hq.app.statement;

/** Body of POST /api/sheets/{sheet}/people/{person}/statement; a blank (or absent) as-of date takes the statement now. */
public record StatementRequest(String asof) {
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The statements taken of the people on each sheet. */
@Repository
public class Statements {

    private final JdbcTemplate jdbc;

    public Statements(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * Per person on the sheet with a statement: the count, the last one's due-total and date (the date it was taken as
     * of, else the sheet's today then), and a line per statement, oldest first by date.
     */
    public List<StatementSummary> list(String sheet) {
        Map<Long, List<StatementSummary.Line>> lines = new HashMap<>();
        jdbc.query("""
                SELECT person, due_total, COALESCE(as_of, taken_on) AS stated_on FROM statement WHERE sheet = ?
                ORDER BY person, stated_on, seq, id""", rs -> {
            lines.computeIfAbsent(rs.getLong("person"), p -> new ArrayList<>()).add(new StatementSummary.Line(
                    rs.getDate("stated_on").toLocalDate().toString(), figure(rs.getBigDecimal("due_total"))));
        }, sheet);
        return jdbc.query("""
                SELECT s.person, (SELECT COUNT(*) FROM statement c WHERE c.sheet = s.sheet AND c.person = s.person)
                  AS taken, s.due_total, COALESCE(s.as_of, s.taken_on) AS stated_on FROM statement s
                WHERE s.sheet = ? AND NOT EXISTS (SELECT 1 FROM statement o WHERE o.sheet = s.sheet
                  AND o.person = s.person AND (o.seq > s.seq OR (o.seq = s.seq AND o.id > s.id)))
                ORDER BY s.person""", (rs, i) -> {
            long person = rs.getLong("person");
            return new StatementSummary(person, rs.getInt("taken"), figure(rs.getBigDecimal("due_total")),
                    rs.getDate("stated_on").toLocalDate().toString(), lines.getOrDefault(person, List.of()));
        }, sheet);
    }

    private static String figure(BigDecimal due) {
        return due == null ? "n/a" : due.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
    }

    /**
     * Records a statement of the person: their due-total (null when n/a), taken on the date, as of a date (null when
     * taken now).
     */
    public void add(String sheet, long person, BigDecimal dueTotal, LocalDate takenOn, LocalDate asOf) {
        jdbc.update("INSERT INTO statement (sheet, person, due_total, taken_on, as_of, seq) VALUES (?, ?, ?, ?, ?,"
                + " (SELECT COALESCE(MAX(s.seq), 0) + 1 FROM statement s WHERE s.sheet = ? AND s.person = ?))", sheet,
                person, dueTotal, Date.valueOf(takenOn), asOf == null ? null : Date.valueOf(asOf), sheet, person);
    }

    /**
     * Moves the person's statements to the person {@code into} on the sheet {@code to}, keeping their order. When
     * that person has statements of their own, the moved ones are placed before them, so their last stays theirs.
     */
    public void move(String sheet, long person, String to, long into) {
        Long shift = jdbc.queryForObject("SELECT (SELECT MIN(seq) FROM statement WHERE sheet = ? AND person = ?)"
                + " - (SELECT MAX(seq) FROM statement WHERE sheet = ? AND person = ?) - 1", Long.class, to, into, sheet,
                person);
        jdbc.update("UPDATE statement SET sheet = ?, person = ?, seq = seq + ? WHERE sheet = ? AND person = ?", to, into,
                shift == null ? 0L : shift, sheet, person);
    }

    /** The person's last statement, if they have one. */
    public Optional<Taken> last(String sheet, long person) {
        return jdbc.query("SELECT id, due_total FROM statement WHERE sheet = ? AND person = ? ORDER BY seq DESC, id DESC LIMIT 1",
                (rs, i) -> new Taken(rs.getLong("id"), rs.getBigDecimal("due_total")), sheet, person)
                .stream().findFirst();
    }

    /** Removes the statement. */
    public void delete(String sheet, long id) {
        jdbc.update("DELETE FROM statement WHERE sheet = ? AND id = ?", sheet, id);
    }

    /** A statement taken: its id and due-total (null when n/a). */
    public record Taken(long id, BigDecimal dueTotal) {
    }
}
package net.officefloor.hq.app.statement;

import java.util.List;

/**
 * A person's statements as the screen shows them: how many have been taken, and the last one's due-total (two
 * decimals, or n/a) and date (ISO yyyy-MM-dd, the date it was taken as of, else the sheet's today when it was taken),
 * and a line per statement standing, "<date> <due-total>", oldest first by date.
 */
public record StatementSummary(long person, int count, String lastDueTotal, String lastDate, List<Line> lines) {

    /** One statement standing: its date and due-total (two decimals, or n/a). */
    public record Line(String date, String dueTotal) {
    }
}
